// src/Home.jsx
import React from "react";
import { useNavigate } from "react-router-dom";

// Exemple données projets
const projects = [
  {
    id: "pos",
    title: "Système de Gestion POS",
    image:
      "https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=60", // remplace par ta propre image
    summary: "Application web complète de gestion de points de vente.",
  },
  {
    id: "autre-projet",
    title: "Autre Projet Exemple",
    image:
      "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=60",
    summary: "Description courte d’un autre projet.",
  },
];

export default function Home() {
  const navigate = useNavigate();

  return (
    <div style={{ maxWidth: 900, margin: "auto", padding: 20, fontFamily: "Arial, sans-serif" }}>
      {/* Section A propos */}
      <section style={{ marginBottom: 40 }}>
        <h1>Aziz Ben Mohamed</h1>
        <p>
          Développeur Full-Stack passionné, spécialisé en développement web, data science et solutions
          métiers. Rigoureux et toujours en quête d’apprentissage.
        </p>
        <h3>Compétences</h3>
        <ul>
          <li>React.js, Node.js, Express, REST API</li>
          <li>Base de données : MySQL, MongoDB</li>
          <li>Machine Learning & Data Analysis</li>
          <li>Git, Docker, CI/CD</li>
        </ul>
        <h3>Parcours</h3>
        <p>
          Licence en Informatique de Gestion, Master en Ingénierie des Systèmes d’Information et Data Science. Plusieurs projets réalisés en développement full-stack et analyse de données.
        </p>
      </section>

      {/* Galerie projets */}
      <section>
        <h2>Mes Projets</h2>
        <div
          style={{
            display: "flex",
            gap: 20,
            flexWrap: "wrap",
            justifyContent: "center",
          }}
        >
          {projects.map((proj) => (
            <div
              key={proj.id}
              onClick={() => navigate(`/projet/${proj.id}`)}
              style={{
                cursor: "pointer",
                width: 250,
                border: "1px solid #ccc",
                borderRadius: 8,
                overflow: "hidden",
                boxShadow: "0 2px 5px rgb(0 0 0 / 0.1)",
              }}
            >
              <img src={proj.image} alt={proj.title} style={{ width: "100%", height: 150, objectFit: "cover" }} />
              <div style={{ padding: 10 }}>
                <h3 style={{ margin: "0 0 5px" }}>{proj.title}</h3>
                <p style={{ fontSize: 14, color: "#555" }}>{proj.summary}</p>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}
